import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadPermanentMarker = makeLoadFont('PermanentMarker');

// Load font at module level to ensure it's ready before frame 0
const { fontFamily: markerFontFamily } = loadPermanentMarker();

// ==========================================
// SCHEMA
// ==========================================


export type WhiteboardAnimationProps = Record<string, any>;

// ==========================================
// HELPER COMPONENTS
// ==========================================

// Renders an SVG path that draws itself on over a frame range, and can optionally un-draw.
const AnimatedWhiteboardPath: React.FC<{
  d: string;
  stroke: string;
  strokeWidth: number;
  startFrame: number;
  endFrame: number;
  eraseStartFrame?: number;
  eraseEndFrame?: number;
  fill?: string;
  fillStartFrame?: number;
  fillEndFrame?: number;
}> = ({ d, stroke, strokeWidth, startFrame, endFrame, eraseStartFrame, eraseEndFrame, fill, fillStartFrame, fillEndFrame }) => {
  const frame = useCurrentFrame();

  // Draw forward
  let progress = interpolate(frame, [startFrame, endFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Erase backward if defined
  if (eraseStartFrame && eraseEndFrame && frame >= eraseStartFrame) {
    progress = interpolate(frame, [eraseStartFrame, eraseEndFrame], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  }

  // Pre-entrance hidden state
  if (progress <= 0) return null;

  // Evolve the path properties to the current progress length
  const evolution = evolvePath(progress, d);

  // Handle optional fill fading in/out
  let currentFillOpacity = 0;
  if (fill && fillStartFrame && fillEndFrame) {
    currentFillOpacity = interpolate(frame, [fillStartFrame, fillEndFrame], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    // Fade out quickly if erasing
    if (eraseStartFrame && frame >= eraseStartFrame) {
      currentFillOpacity = interpolate(frame, [eraseStartFrame, eraseStartFrame + 10], [1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
  }

  return (
    <>
      {/* Fill layer (rendered underneath stroke if present) */}
      {fill && currentFillOpacity > 0 && (
        <path
          d={d}
          fill={fill}
          opacity={currentFillOpacity}
          style={{ transition: "none" }}
        />
      )}
      {/* Stroke layer */}
      <path
        d={d}
        strokeDasharray={evolution.strokeDasharray}
        strokeDashoffset={evolution.strokeDashoffset}
        fill="none"
        stroke={stroke}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ transition: "none" }}
      />
    </>
  );
};

// ==========================================
// MAIN COMPONENT
// ==========================================
export const WhiteboardAnimation: React.FC<WhiteboardAnimationProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 14,
  inkColor = "#1A1A1A",
  tealAccent = "#2FA090",
  orangeAccent = "#E8873C",
  footerText = "MARK KENTWELL | FLOWZONE",
  cloudText = "BLUE SKY",
  finalTextLine1 = "BUILD",
  finalTextLine2 = "WHERE YOU",
  finalTextLine3 = "LEAK.",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Master scale factor based on a 1920x1080 baseline design.
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // ==========================================
  // SCENE TIMING CONSTANTS (30fps)
  // Stage 1 (0.0-2.6s) -> frames 0-78
  // Stage 2 (2.6-5.0s) -> frames 78-150
  // Stage 3 (5.0-7.6s) -> frames 150-228
  // Stage 4 (7.6-9.4s) -> frames 228-282 (Erase right)
  // Stage 5 (9.4-11.6s) -> frames 282-348 (Patch hole)
  // Stage 6 (11.6-14.0s) -> frames 348-420 (Final Text)
  // ==========================================

  // Generate drip spawn frames dynamically between start and patch frames
  const dripFrames = useMemo(() => {
    return Array.from({ length: 15 })
      .map((_, i) => 78 + i * 18)
      .filter((f) => f < 282); // Stop generating when patch is applied
  }, []);

  // Puddle growth logic based on how many drips have fully landed
  const landedDripCount = useMemo(() => {
    return dripFrames.filter((f) => frame > f + 15).length;
  }, [frame, dripFrames]);
  
  const puddleScaleX = interpolate(landedDripCount, [0, 8], [0.3, 1], { extrapolateRight: "clamp" });
  const puddleScaleY = interpolate(landedDripCount, [0, 8], [0.3, 1], { extrapolateRight: "clamp" });

  // ==========================================
  // PATH DEFINITIONS (Designed at 1920x1080 scale)
  // ==========================================
  const bucketPaths = {
    backRim: "M 300 250 C 300 200, 700 200, 700 250",
    frontRim: "M 300 250 C 300 300, 700 300, 700 250",
    body: "M 320 280 L 380 750 C 420 780, 580 780, 620 750 L 680 280",
    handle: "M 280 250 C 250 -50, 750 -50, 720 250",
    handleLeftKnob: "M 290 250 A 10 10 0 1 0 290.1 250", // Pseudo-circle
    handleRightKnob: "M 710 250 A 10 10 0 1 0 710.1 250",
    decPatch: "M 560 550 L 640 540 L 650 620 L 570 630 Z",
    decPatchStitch1: "M 590 540 L 595 560",
    decPatchStitch2: "M 620 535 L 625 555",
    decPatchStitch3: "M 655 570 L 635 575",
    decPatchStitch4: "M 565 600 L 585 595",
    activeHole: "M 400 650 L 415 620 L 435 660 L 450 640 L 460 670 L 440 690 L 410 680 Z",
  };

  const rightScenePaths = {
    cloud:
      "M 1150 450 C 1100 450, 1100 350, 1200 350 C 1250 250, 1400 250, 1450 350 C 1550 300, 1650 350, 1650 450 C 1750 500, 1650 600, 1550 550 C 1450 650, 1250 650, 1200 550 C 1100 600, 1050 500, 1150 450 Z",
    sparkle1A: "M 1150 260 L 1150 300",
    sparkle1B: "M 1130 280 L 1170 280",
    sparkle2A: "M 1600 260 L 1600 300",
    sparkle2B: "M 1580 280 L 1620 280",
    sparkle3A: "M 1650 580 L 1650 620",
    sparkle3B: "M 1630 600 L 1670 600",
  };

  const patchPaths = {
    outline: "M 390 610 L 470 590 L 480 710 L 400 730 Z",
    fillZigzag: "M 405 630 L 460 615 L 410 650 L 465 640 L 415 680 L 470 660 L 420 710",
    stitch1: "M 420 595 L 425 625",
    stitch2: "M 450 590 L 455 620",
    stitch3: "M 485 640 L 460 645",
    stitch4: "M 490 680 L 465 685",
    stitch5: "M 415 725 L 420 695",
    stitch6: "M 450 715 L 455 685",
    stitch7: "M 385 680 L 410 675",
    stitch8: "M 380 640 L 405 645",
  };

  const puddlePath =
    "M 250 900 C 200 870, 400 850, 500 880 C 600 850, 750 870, 700 900 C 750 930, 600 950, 500 920 C 400 950, 200 930, 250 900 Z";
  
  const dripPath = "M 0 0 C 15 20, 15 40, 0 40 C -15 40, -15 20, 0 0 Z";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Filter definition for marker "boil" effect */}
      <svg style={{ position: "absolute", width: 0, height: 0 }}>
        <defs>
          <filter id="marker-boil">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.15"
              numOctaves="2"
              result="noise"
              seed={Math.floor(frame / 4)}
            />
            <feDisplacementMap in="SourceGraphic" in2="noise" scale="3" xChannelSelector="R" yChannelSelector="G" />
          </filter>

          {/* Clip paths for text revealing (simulating left-to-right writing) */}
          {/* Cloud Text Reveal */}
          <clipPath id="cloud-text-clip">
            <rect 
              x="1100" 
              y="300" 
              width={interpolate(frame, [180, 210], [0, 600], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }) - (frame >= 235 ? interpolate(frame, [235, 255], [0, 600], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }) : 0)} 
              height="300" 
            />
          </clipPath>

          {/* Final Text Reveal Line 1 */}
          <clipPath id="final-text-clip-1">
            <rect x="1100" y="300" width={interpolate(frame, [348, 368], [0, 700], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })} height="150" />
          </clipPath>
          {/* Final Text Reveal Line 2 */}
          <clipPath id="final-text-clip-2">
            <rect x="1100" y="450" width={interpolate(frame, [368, 388], [0, 700], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })} height="150" />
          </clipPath>
          {/* Final Text Reveal Line 3 */}
          <clipPath id="final-text-clip-3">
            <rect x="1100" y="600" width={interpolate(frame, [388, 410], [0, 700], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })} height="150" />
          </clipPath>

          {/* Puddle Label Reveal */}
          <clipPath id="puddle-label-clip">
            <rect x="730" y="800" width={interpolate(frame, [120, 140], [0, 200], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })} height="200" />
          </clipPath>

          {/* Footer Reveal */}
          <clipPath id="footer-clip">
            <rect x="30" y="980" width={interpolate(frame, [0, 15], [0, 800], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })} height="100" />
          </clipPath>
        </defs>
      </svg>

      {/* Main Container Scaled to Canvas Size */}
      <AbsoluteFill
        style={{
          transform: `scale(${s})`,
          transformOrigin: "top left",
          width: 1920,
          height: 1080,
          filter: "url(#marker-boil)",
          fontFamily: markerFontFamily,
        }}
      >
        <svg width={1920} height={1080} style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}>
          
          {/* Stage 1: Left Bucket & Detail Patch */}
          <g>
            <AnimatedWhiteboardPath d={bucketPaths.handle} stroke={inkColor} strokeWidth={8} startFrame={0} endFrame={20} />
            <AnimatedWhiteboardPath d={bucketPaths.backRim} stroke={inkColor} strokeWidth={6} startFrame={10} endFrame={30} />
            <AnimatedWhiteboardPath d={bucketPaths.body} stroke={inkColor} strokeWidth={8} startFrame={20} endFrame={50} />
            <AnimatedWhiteboardPath d={bucketPaths.frontRim} stroke={inkColor} strokeWidth={8} startFrame={40} endFrame={60} />
            <AnimatedWhiteboardPath d={bucketPaths.handleLeftKnob} stroke={inkColor} strokeWidth={10} startFrame={15} endFrame={20} />
            <AnimatedWhiteboardPath d={bucketPaths.handleRightKnob} stroke={inkColor} strokeWidth={10} startFrame={18} endFrame={23} />
            
            {/* Decorative Right-Side Patch */}
            <AnimatedWhiteboardPath d={bucketPaths.decPatch} stroke={inkColor} strokeWidth={6} startFrame={30} endFrame={45} />
            <AnimatedWhiteboardPath d={bucketPaths.decPatchStitch1} stroke={inkColor} strokeWidth={4} startFrame={45} endFrame={48} />
            <AnimatedWhiteboardPath d={bucketPaths.decPatchStitch2} stroke={inkColor} strokeWidth={4} startFrame={48} endFrame={51} />
            <AnimatedWhiteboardPath d={bucketPaths.decPatchStitch3} stroke={inkColor} strokeWidth={4} startFrame={51} endFrame={54} />
            <AnimatedWhiteboardPath d={bucketPaths.decPatchStitch4} stroke={inkColor} strokeWidth={4} startFrame={54} endFrame={57} />

            {/* The Active Leak Hole */}
            <AnimatedWhiteboardPath d={bucketPaths.activeHole} stroke={inkColor} strokeWidth={6} startFrame={50} endFrame={78} />
          </g>

          {/* Stage 2: Drips & Puddle */}
          <g>
            {/* Puddle Outline */}
            <AnimatedWhiteboardPath 
              d={puddlePath} 
              stroke={inkColor} 
              strokeWidth={6} 
              startFrame={80} 
              endFrame={100}
            />
            {/* Puddle Teal Fill - scales up as drips land */}
            <g style={{ transformOrigin: "475px 900px", transform: `scale(${puddleScaleX}, ${puddleScaleY})` }}>
              <path 
                d={puddlePath} 
                fill={tealAccent} 
                opacity={frame >= 100 ? interpolate(frame, [100, 110], [0, 1], { extrapolateRight: "clamp" }) : 0} 
                style={{ transition: "none" }}
              />
            </g>

            {/* Drip Generation */}
            {dripFrames.map((startFrame, idx) => {
              // Only render drip while active
              if (frame < startFrame || frame > startFrame + 15) return null;
              
              const fallProgress = interpolate(frame, [startFrame, startFrame + 15], [0, 1]);
              const dripY = interpolate(fallProgress, [0, 1], [670, 890]);
              const dripScale = interpolate(fallProgress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]);

              return (
                <path
                  key={`drip-${idx}`}
                  d={dripPath}
                  fill={tealAccent}
                  stroke={inkColor}
                  strokeWidth={4}
                  style={{
                    transform: `translate(435px, ${dripY}px) scale(${dripScale})`,
                    transition: "none"
                  }}
                />
              );
            })}
          </g>

          {/* Stage 3 & 4: Right Cloud (Draws then Erases) */}
          <g>
            <AnimatedWhiteboardPath 
              d={rightScenePaths.cloud} 
              stroke={inkColor} 
              strokeWidth={8} 
              startFrame={150} 
              endFrame={180} 
              eraseStartFrame={250} 
              eraseEndFrame={280} 
            />
            <AnimatedWhiteboardPath d={rightScenePaths.sparkle1A} stroke={inkColor} strokeWidth={6} startFrame={200} endFrame={205} eraseStartFrame={233} eraseEndFrame={235} />
            <AnimatedWhiteboardPath d={rightScenePaths.sparkle1B} stroke={inkColor} strokeWidth={6} startFrame={205} endFrame={210} eraseStartFrame={231} eraseEndFrame={233} />
            <AnimatedWhiteboardPath d={rightScenePaths.sparkle2A} stroke={inkColor} strokeWidth={6} startFrame={210} endFrame={215} eraseStartFrame={229} eraseEndFrame={231} />
            <AnimatedWhiteboardPath d={rightScenePaths.sparkle2B} stroke={inkColor} strokeWidth={6} startFrame={215} endFrame={220} eraseStartFrame={228} eraseEndFrame={229} />
            <AnimatedWhiteboardPath d={rightScenePaths.sparkle3A} stroke={inkColor} strokeWidth={6} startFrame={215} endFrame={220} eraseStartFrame={230} eraseEndFrame={232} />
            <AnimatedWhiteboardPath d={rightScenePaths.sparkle3B} stroke={inkColor} strokeWidth={6} startFrame={220} endFrame={225} eraseStartFrame={228} eraseEndFrame={230} />
          </g>

          {/* Stage 5: Orange Patch over hole */}
          <g>
            <AnimatedWhiteboardPath 
              d={patchPaths.outline} 
              stroke={inkColor} 
              strokeWidth={8} 
              startFrame={282} 
              endFrame={300} 
            />
            {/* Hand-drawn scrub fill */}
            <AnimatedWhiteboardPath 
              d={patchPaths.fillZigzag} 
              stroke={orangeAccent} 
              strokeWidth={30} 
              startFrame={290} 
              endFrame={310} 
            />
            {/* Stitches */}
            <AnimatedWhiteboardPath d={patchPaths.stitch1} stroke={inkColor} strokeWidth={6} startFrame={310} endFrame={313} />
            <AnimatedWhiteboardPath d={patchPaths.stitch2} stroke={inkColor} strokeWidth={6} startFrame={313} endFrame={316} />
            <AnimatedWhiteboardPath d={patchPaths.stitch3} stroke={inkColor} strokeWidth={6} startFrame={316} endFrame={319} />
            <AnimatedWhiteboardPath d={patchPaths.stitch4} stroke={inkColor} strokeWidth={6} startFrame={319} endFrame={322} />
            <AnimatedWhiteboardPath d={patchPaths.stitch5} stroke={inkColor} strokeWidth={6} startFrame={322} endFrame={325} />
            <AnimatedWhiteboardPath d={patchPaths.stitch6} stroke={inkColor} strokeWidth={6} startFrame={325} endFrame={328} />
            <AnimatedWhiteboardPath d={patchPaths.stitch7} stroke={inkColor} strokeWidth={6} startFrame={328} endFrame={331} />
            <AnimatedWhiteboardPath d={patchPaths.stitch8} stroke={inkColor} strokeWidth={6} startFrame={331} endFrame={334} />
          </g>
        </svg>

        {/* Text Layer (HTML overlaid on exact SVG coordinates, clipped for drawing effect) */}
        
        {/* Footer */}
        <div style={{ position: "absolute", left: 50, top: 1000, fontSize: 32, color: "#C9C9C9", clipPath: "url(#footer-clip)", fontWeight: 400 }}>
          {footerText}
        </div>

        {/* Puddle Label '$' */}
        <div style={{ position: "absolute", left: 750, top: 820, fontSize: 100, color: inkColor, clipPath: "url(#puddle-label-clip)" }}>
          $
        </div>

        {/* Cloud Label (Draws then Erases) */}
        <div style={{ position: "absolute", left: 1400, top: 450, transform: "translate(-50%, -50%)", textAlign: "center", fontSize: 80, color: inkColor, clipPath: "url(#cloud-text-clip)" }}>
          {cloudText}
        </div>

        {/* Final Text (Right side cleared space) */}
        <div style={{ position: "absolute", left: 1400, top: 400, transform: "translate(-50%, -50%)", textAlign: "center", fontSize: 110, color: inkColor, clipPath: "url(#final-text-clip-1)" }}>
          {finalTextLine1}
        </div>
        <div style={{ position: "absolute", left: 1400, top: 510, transform: "translate(-50%, -50%)", textAlign: "center", fontSize: 110, color: inkColor, clipPath: "url(#final-text-clip-2)" }}>
          {finalTextLine2}
        </div>
        <div style={{ position: "absolute", left: 1400, top: 620, transform: "translate(-50%, -50%)", textAlign: "center", fontSize: 110, color: inkColor, clipPath: "url(#final-text-clip-3)" }}>
          {finalTextLine3}
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default WhiteboardAnimation;